fn average(temps: &[7]Float64) -> Float64 {
  var sum = 0.0;
  var i = 0;
  while i < 7 {
    sum = sum + temps[i];
    i = i + 1;
  }
  return sum / 7.0;
}

fn hottest_day(temps: &[7]Float64) -> Int {
  var max_idx = 0;
  var i = 1;
  while i < 7 {
    if temps[i] > temps[max_idx] { max_idx = i; }
    i = i + 1;
  }
  return max_idx;
}

fn main() -> Int {
  let temps = [20.0, 22.5, 25.0, 24.0, 21.5, 19.0, 23.0];
  let avg = average(&temps);
  return (avg * 10.0) as Int;
}
